def fix_spaces(text):
    if not text:
        return text

    parts = text.split(' ')
    result = []
    consecutive_spaces = 0

    for part in parts:
        if part == '':
            consecutive_spaces += 1
        else:
            if consecutive_spaces > 2:
                result.append('-')
            elif consecutive_spaces > 0:
                result.append('_')
            result.append(part)
            consecutive_spaces = 0

    if consecutive_spaces > 2:
        result.append('-')
    elif consecutive_spaces > 0:
        result.append('_')

    return ''.join(result)

